- #0 Best of Names 7:180; 17:110; 20:8; 59:22-24
- #1 الرحمن     رحمت کوونکی (ټولو مخلوقاتو ته پراخه رحمت لرونکی)  1:3; 17:110
- #2 الرحيم     بې حده مهربان (په مومنانو باندې خاص رحمت کوونکی)  2:163; 3:31; 4:100; 5:3
- #3 الملك     پاچا (د خپل سلطنت مالک)  20:114; 23:116; 59:23
- #4 القدوس     پاک ذات (د هر عيب څخه پاک)  59:23; 62:1
- #5 السلام     سوله ورکوونکی (د هر عيب څخه پاک)  59:23
- #6 المؤمن     امن ورکوونکی (ایمان خوندي کوونکی)  59:23
- #7 المهيمن     نګهبان (د ټولو چارو څارونکی او ساتونکی)  59:23
- #8 العزيز     زورور (بې نظیره قوي، نه ماتېدونکی)  3:6; 4:158; 9:40; 48:7
- #9 الجبار     جبار (په زور خپل امر نافذ کوونکی، مات شوي جوړونکی)  59:23
- #10 المتكبر     لوړ ذات (د عظمت خاوند، له هر عيب څخه پاک)  59:23
- #11 الخالق     پيدا کوونکی (له هيچا نه پیدا کوونکی)  6:102; 13:16; 39:62; 40:62; 59:24
- #12 البارئ     برېښندونکی (په سموالی سره پیدا کوونکی)  59:24
- #13 المصور     صورت ورکوونکی (د هر شي بڼه جوړونکی)  59:24
- #14 الغفار     ډېر بخښونکی (د بندګانو ګناهونه پټوونکی)  20:82; 38:66; 39:5; 40:42; 71:10
- #15 القهار     برلاسی (د ټولو برلاسی او ماتوونکی)  13:16; 14:48; 38:65; 39:4; 40:16
- #16 الوهاب     ډېر ورکوونکی (بې غوښتنې ډالۍ ورکوونکی)  3:8; 38:9; 38:35
- #17 الرزاق     روزي ورکوونکی (د ټولو رزق پیدا کوونکی او رسوونکی)  51:58
- #18 الفتاح     پرانيستونکی (د رحمت خزانې پرانيستونکی)  34:26
- #19 العليم     ښه پوه (هر څه ته پوه)  2:158; 3:92; 4:35; 24:41; 33:40
