- هغه وويل: "اې زما قومه! تاسو ته څه ښكاري؟ كه زه د خپل رب له لوري په څرګند دليل باندې يم؟" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- دا د هغه څه په بدل كې دى چې ستاسو لاسونو مخكې ليږلي دي، او الله د بنده ګانو ظالم نه دى. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- دوى ته په دې نړۍ كې رسوايي ده او دوى ته په اخرت كې لوى عذاب دى. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- هغه څه چې په اسمانونو او ځمكه كې دي، او الله د ساتونكي په توګه بس دى. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- مګر هغه كسان چې ايمان يې راوړى او نيك عملونه يې كړي دي؛ دوى ته بې پايه اجر دى. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- چې ته ما سره هغه څه شريك كړې چې ستا ته د هغه علم نشته؛ نو د هغوى اطاعت مه كوه. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- بېشكه دا يو نصيحت دى؛ نو هر څوك چې وغواړي، د خپل رب لار غوره كړي. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- او هر څوك چې شكر وكړي، نو شكر يې د خپل نفس لپاره دى؛ او هر څوك چې ناشكري وكړي. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- هغه كسان چې لمونځ قايموي او زكات وركوي او دوى په اخرت يقين لري. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- (موږ ايمان راوړ) په ابراهيم، اسماعيل، اسحاق، يعقوب او اولادونو، او هغه څه چې موسى او عيسى ته وركړل شوي وو. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- په ډلو ډلو، تر هغه چې دوى ورته راشي، او د هغې دروازې به پرانيستل شي، او د هغې ساتونكي به دوى ته ووايي. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- الله تاسو ته د خپلو قسمونو په بېګټو خبرو نه نيسي، خو تاسو ته هغه څه نيسي چې. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- رحمت، دوى پكې خوشحالېږي، او كه دوى ته د هغوى د لاسونو د كړو كارونو له امله كومه تكليف ورسيږي. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- جنتونه چې لاندې يې ويالې بهېږي، په دوى كې به تل تر تله اوسي، او د عمل كوونكو اجر څومره ښه دى! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- الله هغه څه پېژني چې په اسمانونو او ځمكه كې دي، او الله. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- د الله اطاعت وكړئ او د رسول اطاعت وكړئ؛ كه تاسو مخ واړوئ، نو په هغه باندې (يواځې تبليغ) دى. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- دوى ته د دوى اجر د دوى د رب په نزد دى، او نه په دوى باندې څه وېره شته او نه دوى. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- او دوى وويل: "ایا كله چې موږ هډوكي او خاوره شو، ایا موږ به بيا په نوي پيدايښت سره پاڅول كېږو؟" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- او دوى به د خپل ځان لپاره د الله پرته بل نه ساتونكى او نه مرستيال پيدا كړي. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "ته څومره وخت پاتې شوې؟" هغه وويل: "زه یوه ورځ یا د ورځې يوه برخه پاتې شوم." هغه وويل. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- تل تر تله د قيامت تر ورځې پورې، د الله پرته بل څوك دى چې تاسو ته راوړى شي؟ (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- هر څوك چې نيك عمل وكړي، نر وي يا ښځه، او هغه مومن وي. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- هغه كسان چې د الله له لارې نه خلک منع كوي او غواړي چې هغه كږه كړي، او دوى په اخرت (باندې كافران دي). (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ته چېرته چې غواړې وخورې، خو دې ونې ته مه نږدې كېږه، كه نه نو تاسو به له ظالمانو نه شئ. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ووايه: "اې زما قومه! تاسو په خپل ځاى عمل كوئ، زه هم عمل كوم، نو ژر به تاسو پوه شئ." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- بېشكه تاوان كوونكي هغه كسان دي چې د قيامت په ورځ به خپل ځانونه او خپلې كورنۍ تاوان كړي، خبردار. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- هر څوك چې نېغه لار ونيسي، نو د خپل ځان لپاره يې نيسي؛ او هر څوك چې ګمراه شي، نو د خپل ځان لپاره ګمراه كېږي؛ او. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- او هغه كسان چې كافر شوي، وايي: "دې ته د هغه د رب له لوري ولې كومه نښه نه ده راكښكته شوې؟" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- هغه چې ستاسو لپاره شپه جوړه كړې چې تاسو پكې ارام وكړئ، او ورځ چې تاسو وګورئ، بېشكه. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- د هغه ورځې نه مخكې چې په هغې كې نه خرڅلاو شته او نه دوستي. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- دوى دې فكر وكړي چې د دوى ملګرى لېونى نه دى؛ هغه يوازې ښكاره وېروونكى دى. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- دوى به پكې تل تر تله اوسي، نه به له دوى نه عذاب سپك كېږي او نه به دوى ته مهلت وركول كېږي. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- خپلې سترګې هغه څه ته مه غځوه چې موږ د دوى له ځينو څخه يې د خوند لپاره وركړي دي. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- او خلکو ته د هغوى شيان مه كموئ او په ځمكه كې فساد مه كوئ. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- او سلام دې وي پر هغه باندې په هغه ورځ چې زېږېدلى دى، او په هغه ورځ چې مري، او په هغه ورځ چې بيا ژوندى پاڅول كېږي. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- اې زما قومه! تاسو په خپل ځاى عمل كوئ، زه هم عمل كوم، نو ژر به تاسو پوه شئ چې څوك. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- او د هيڅ رسول لپاره دا نه و چې د الله له اجازې پرته كومه نښه راوړي. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- بيا به هر چا ته د هغه د كړو كارونو بدله په بشپړه توګه وركړل شي، او دوى ته به ظلم نه كېږي. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- نر وي يا ښځه، او هغه مومن وي، نو داسې كسان به جنت ته داخل شي. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- هغه اولاد نه دى نيولى او نه د هغه لپاره د حكومت په برخه كې كوم شريك شته. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- او هر چا ته چې الله نېغه لار وركړي، نو هغه نېغه لار موندونكى دى؛ او هر چا ته چې هغه ګمراه كړي. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- وګوره چې دوى تا ته څنګه مثالونه وايي، نو ګمراه شول، او لار يې ونه مونده. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- ووايه: "زه د wielkiego ورځې له عذابه وېرېږم كه زه د خپل رب نافرماني وكړم." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- د دوى دواړو شرم ځايونه ښكاره شول، او دوى د جنت له پاڼو نه خپل ځانونه پټول پيل كړل. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- او تاسو د الله پرته هغه څوك بولي چې تاسو يې بللى شئ، كه تاسو رښتيني ياست. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
