- ایا موږ د الله پرېښودو سره هغه څه رابلو چې نه زمونږ ګټه كوي او نه زيان؟ (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- دوى پر هغه څه ایمان راوړي چې تا ته نازل شوى دى او پر هغه څه چې تر تا مخكې نازل شوي دي. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- ایا ته نه وینې چې الله له اسمان نه اوبه نازلوي؟ (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- كله چې هغه د یو كار اراده وكړي، نو د هغه لپاره وايي: شه، نو هغه شي. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- او مدین ته د دوى ورور شعیب (ولېږو). هغه وویل: اې زما قومه! د الله عبادت وكړئ. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- دا د غیب له خبرونو څخه دي، چې موږ تا ته وحي كوو؛ ته دا نه پېژندلې. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- كله چې د دوى موده راشي، نو نه یوه ساعته وروسته كېږي او نه مخكې كېږي. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- تاسو د شیطان د قدمونو پیروي مه كوئ، بېشكه هغه ستاسو ښكاره دښمن دى. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- له خلقو څخه ځينې داسې كسان دي چې د الله په باره كې بې له علمه جګړه كوي. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- الله هغه چاته وركوي چې يې وغواړي، او الله لوى فضل والا دى. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- هره نفس ته به د هغه د كړو عملونو پوره بدله وركول كېږي، او دوى ته به ظلم نه كېږي. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- هغه نفس مه وژنئ چې الله حرام كړى دى، مګر د حق په سبب. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- كله چې هغه د یو كار اراده وكړي، نو د هغه لپاره وايي: شه. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- تاسو د جهنم د دروازو نه داخل شئ، په هغه كې تل تر تله اوسېدونكي يئ؛ نو د متكبرانو ځاى څومره بد دى! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ایا ته هغه كسان نه وینې چې د كتاب څخه برخه وركړل شوې ده؟ (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- د دوى لپاره هغه جنتونه دي چې لاندې يې سیندونه بهیږي، دوى به پكې تل تر تله اوسېدونكي وي. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- اې زما قومه! تاسو په خپل ځاى عمل كوئ، زه هم عامل یم، نو ژر به پوه شئ. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- څوك چې د الله او د هغه د رسول مخالفت كوي، نو د هغه لپاره د جهنم اور دى، هغه به پكې تل تر تله اوسېدونكى وي. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- موږ د دوى په زړونو باندې پردې اچولي دي، چې دوى يې پوه نه شي، او د دوى په غوږونو كې دروندوالى. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- هر هغه كلي ته چې موږ وېروونكى ولېږو، نو د هغه مالدارو خلکو وویل: بېشكه موږ. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- دوى وویل: زمونږ لپاره له خپل رب نه دعا وكړه، چې زمونږ ته واضح كړي چې هغه څه شي. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- دوى به خامخا ووايي: الله. ته ووایه: ټولې ستاينې د الله لپاره دي! خو د دوى ډېرى. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- د هغه د قوم ځواب یوازې دا وو چې دوى وویل: دوى وشړئ. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- چې لاندې يې سیندونه بهیږي، دوى به پكې تل تر تله اوسېدونكي وي؛ دا لویه كامیابي ده. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- دغه خلق د خپل رب له لارې پر نېغه لار دي او همدوى كامیاب دي. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- هغه څوك چې په هغه باندې سپكاوى كوونكى عذاب راشي او پر هغه باندې دايمي عذاب راشي. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- تاسو په ځمكه كې سفر وكړئ، پس وګورئ چې د هغو دروغ ګڼونكو انجام څنګه وو. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- دوى به هېڅكله د هغه ارزو نه كوي، د هغو عملونو په سبب چې د دوى لاسونو مخكې لېږلي دي، او الله ظالمان ښې پېژني. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- هغه ښه پېژني چې څوك د هغه له لارې نه بېلاره شوى دى، او هغه ښه پېژني. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- بېشكه الله زما رب دى او ستاسو رب دى، نو تاسو د هغه عبادت وكړئ؛ دا نېغه لار ده. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- هغه په خلقو باندې لوى فضل لري، خو د دوى ډېرى شكر نه كوي. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- اسمانونه او ځمكه او هغه څه چې د دواړو په منځ كې دي، موږ يې یوازې د حق او یوې ټاكلې مودې لپاره پیدا كړي دي. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- دوى پرېږده چې په خپلو باطلو خبرو كې ډوب شي او لوبې وكړي، تر څو چې د خپلې هغې ورځې سره مخ شي چې دوى ته يې وعده وركول كېږي. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- كله چې دوى له مومنانو سره مخ شي، وايي: موږ ایمان راوړى دى، او كله چې يو بل سره تنها شي. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- دوى تورات، انجیل او هغه څه چې د خپل رب له جانبه دوى ته نازل شوي دي، قايموي. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- هغه پوهېږي هغه څه چې د دوى په مخ كې دي او هغه څه چې د دوى شاته دي، او دوى د هغه احاطه په خپل علم سره نه شي كولى. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- او هم هغه دى چې اسمانونه او ځمكه يې په شپږو ورځو كې پیدا كړي دي. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- بېشكه په دې كې ستاسو لپاره نښه ده، كه چېرې تاسو مومنان یئ. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- خلقو ته څه شي مانع شو چې ایمان راوړي، كله چې دوى ته نېغه لار راغله؟ (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- دوى د الله لپاره شریكان جوړ كړل، ترڅو د هغه له لارې نه واړوي. ته ووایه: خوند واخلئ. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- دوى تعجب وكړ چې د دوى له همدوى نه یو وېروونكى دوى ته راغى، او كافرو وویل: دا. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- بېشكه ستا رب هغه ښه پېژني چې څوك د هغه له لارې بېلاره شوى دى. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- د هغه چا په شان چې خپل مال د خلکو د ښودلو لپاره خرچوي او په الله ایمان نه راوړي. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- هغه څه چې موږ تاسو ته وركړي دي، له هغه نه د دې (ورځې) تر راتلو مخكې خرچ كړئ. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- هغه تاسو ته هغه څه مسخر كړي دي چې په اسمانونو او ځمكه كې دي. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- او بېشكه موږ په هغه څه كې چې تاسو موږ ته ور بلئ، په شك كې یو. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- بېشكه ستا رب د چا لپاره چې وغواړي، روزي پراخوي او تنګوي. بېشكه هغه. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- د اسمانونو او ځمكې رب او د هغه څه چې د دواړو په منځ كې دي، كه تاسو یقین لرونكي یئ. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- موږ په الله ایمان راوړى دى او په هغه څه چې زمونږ ته نازل شوي دي او په هغه څه چې (ابراهیم، اسماعیل، اسحاق، یعقوب او اولادونو) ته نازل شوي وو. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- او هغو كسانو چې ظلم يې كاوه، یوې سختې چغې ونیول، نو دوى په خپلو كورونو كې پر مخونو لوېدلي پاتې شول. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- په هغه څه كې چې هغه ښځې د خپل نفس په باره كې كوي، پر تاسو باندې هېڅ ګناه نشته. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- ستا رب هغه ښه پېژني چې څوك د هغه له لارې بېلاره شوى دى، او هغه. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- هغه خپلې امر ته روح (وحي) په هغه چا باندې نازلوي چې يې وغواړي، د خپلو بندگانو څخه. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- او موږ عیسی مريم زوی ته ښكاره نښې وركړې او موږ هغه د روح القدس سره قوي كړ. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- دې لپاره چې د قیامت په ورځ د دوى په منځ كې د هغه څه فیصله وكړي چې دوى به پكې اختلاف كاوه. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- موږ د هغه (كلي) پورتنۍ برخه ښكتې برخه وكړه او پر دوى باندې د سوځېدلو خټو كاڼي وورول. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- د دوى لپاره یو شان دى، كه ته دوى وېروې كه نه وېروې، دوى ایمان نه راوړي. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- له خلقو نه، نو كه تاسو رښتیني یئ، نو د مرګ هيله وكړئ. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- د الله (عبادت وكړئ)، تاسو له هغه پرته بل معبود نلرئ. ایا تاسو نه وېرېږئ؟ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- كه موږ تا ته هغه څه وښیو چې موږ يې دوى ته وعده وركوو، یا موږ ته فوت كړو، نو د دوى بېرته راتلل خو زمونږ خواته دي. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- دوى وویل: ایا كله چې موږ مړه شو او خاورې او هډوکي شو، نو ایا موږ بیا ژوندي كېږو؟ (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- بېشكه فضل د الله په لاس كې دى، هغه چا ته وركوي چې يې وغواړي، او الله. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- او تاسو به د پټو او ښكاره څيزونو پېژندونكي ته بېرته وګرځول شئ، نو هغه به تاسو ته د هغو عملونو خبر دركړي چې تاسو به كول. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- اې هغو كسانو چې ایمان يې راوړى دى! د الله هغه نعمت یاد كړئ چې پر تاسو باندې شوى دى، كله چې. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- او موږ تر تا مخكې هم یوازې سړي رسولان لېږلي وو، چې موږ به دوى ته وحي نازلوله. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- هغه به د هغه ګناهونه وبخښي او هغه به هغو جنتونو ته داخل كړي چې لاندې يې سیندونه بهیږي. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- څوك چې ناروغ وي یا په سفر كې وي، نو د نورو ورځو شمېر (به پوره كړي). (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- دوى يواځې د ګمان پیروي كوي او دوى يواځې اټكل كوي. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- د هغه چا لپاره چې د الله او د اخرت ورځې هيله لري، ښه نمونه ده. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- او موږ اسمانونه، ځمكه او هغه څه چې د دواړو په منځ كې دي، يواځې د حق سره پیدا كړي دي. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- خپل لاس په خپل ګېډوان كې واچوه، هغه به بې له عيبه سپین راووځي. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- هغه د خپلې رحمت له مخې چا ته چې وغواړي، ځانګړي كوي، او الله لوى فضل والا دى. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- ایا ته نه پوهېږې چې بېشكه الله د اسمانونو او ځمكې بادشاه دى؟ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- او هغه څه چې تاسو د خپل نفس لپاره مخكې لېږئ، له نېكۍ څخه، نو تاسو به هغه د الله په نزد ومومئ. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- او ته چېرته چې وځې، نو خپل مخ د مسجد الحرام په لور راوګرځوه. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- دوى له تاسو نه مخكې تېر شوي دي، او ته به د الله په طریقه كې هېڅ بدلون ونه مومې. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- هغه چې د هغه لپاره دي هغه څه چې په اسمانونو او ځمكه كې دي. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- او هېڅ ښځه امېدواره نه كېږي او نه زېږوي، مګر د هغه په علم سره. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- هغه شپه، لمر او سپوږمۍ مسخر كړي دي؛ هر یو د خپلې ټاكلې مودې تر وخته روان دى. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- چې لاندې يې سیندونه بهیږي، دوى به پكې تل تر تله اوسېدونكي وي، او دا (د دوى) بدله ده. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- هغه وویل: نه، بلکې ستاسو نفسونو تاسو ته یو كار ښايسته كړى دى؛ نو صبر ښه دى. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- هغه څه چې په اسمانونو او ځمكه كې دي، او بېشكه الله. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- او دوى ته چې كوم رسول راغى، نو دوى به هغه مسخره كاوه. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- دوى وویل: اې موسى! ایا ته (لښتى) اچوې او كه موږ واچوو؟ (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- هغه دى چې تاسو مړه كوي، او ستاسو څخه ځينې د ډېر زوړ عمر خواته بېرته گرځول كېږي، دې لپاره چې. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- د دوى لپاره د خپل رب په نزد هغه جنتونه دي چې لاندې يې سیندونه بهیږي، دوى به پكې تل تر تله اوسېدونكي وي. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- او موږ د دوى په زړونو باندې پردې اچولي دي، چې دوى يې پوه نه شي، او د دوى په غوږونو كې دروندوالى. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- بېشكه د الله وعده رښتینې ده، خو د دوى ډېرى نه پوهېږي. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- دا ځكه چې دوى د الله او د هغه د رسول مخالفت وكړ؛ او څوك چې د الله مخالفت وكړي. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- او په هغه ورځ چې هغه دوى ته غږ وكړي، نو ووايي: زما هغه شریكان چې تاسو به گڼل، چېرته دي؟ (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ایا دوى نه دي كتلي چې بېشكه الله، هغه چې اسمانونه او ځمكه يې پیدا كړي دي، هغه د دوى په شان پیدا كول شي؟ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (هغه) چې تاسو يې له خاورې، بیا له یوې ټوپكې، بیا له. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- دوى به وايي: زموږ ربه! ولې موږ ته یو رسول رانه استولې، چې موږ ستا د نښو پیروي كړې وای؟ (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- بیا د دوى بېرته راتلل د خپل رب خواته دي، نو هغه به دوى ته د هغو عملونو خبر وركړي چې دوى به كول. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- د دوى لپاره د دې هيڅ علم نشته؛ دوى يواځې د ګمان پیروي كوي. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- بېشكه موږ خپل پلرونه په یو دین باندې موندلي دي او موږ د دوى په قدمونو پسې روان یو. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- هغو كسانو ته چې كتاب وركړل شوى وو، دوى اختلاف نه ووكړ، مګر وروسته له هغه چې دوى ته علم راغى. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- او كله چې ابراهیم وویل: اې زما ربه! دا ښار دې امن ښار وګرځوه. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- هغه تاسو ته غوږونه، سترګې او زړونه دركړل؛ تاسو ډېر لږ شكر كوئ. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- هغه كسان چې د الله د نښو په باره كې بې له كوم دلیله جګړه كوي، چې دوى ته راغلى وي. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- نو تاسو د ابراهیم د دین پیروي وكړئ، چې یو طرفه مسلمان و، او هغه له مشركانو نه و. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- او كله چې موږ تاسو د فرعون له خلكو نه وژغورلئ، چې تاسو به يې په سخت عذاب كولو. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
